CREATE OR REPLACE FUNCTION public.post_listing_visible(p public.posts,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT p.status='active' AND (p.visible_after IS NULL OR p.visible_after<=_at) AND (p.job_expires_at IS NULL OR p.job_expires_at>_at) AND CASE WHEN p.module='job' THEN p.created_at+interval '30 days'>_at WHEN p.module='vehicle' THEN CASE WHEN lower(trim(coalesce(p.vehicle_type,''))) NOT IN('car','cars','కారు','కార్లు','కార్') AND trim(coalesce(p.from_place,''))<>'' AND lower(trim(p.from_place))=lower(trim(coalesce(p.to_place,''))) THEN p.created_at+interval '1 day'>_at ELSE p.trip_date IS NOT NULL AND p.trip_date>=(_at AT TIME ZONE 'Asia/Kolkata')::date END ELSE true END $$;
CREATE OR REPLACE FUNCTION public.service_priority_position(_user uuid,_area text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT rank_no::integer FROM (SELECT user_id,row_number() OVER(ORDER BY applied_at,user_id) rank_no FROM public.service_priority_applications WHERE lower(trim(area))=lower(trim(_area)) AND applied_at+interval '1 month'>now() AND public.has_paid_bell(user_id) AND public.account_allowed(user_id)) s WHERE user_id=_user AND rank_no<=10 $$;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN IF NOT public.my_profile_access_ready() THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (public.post_listing_visible(posts) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF p.module='vehicle' AND NOT (public.has_paid_bell(auth.uid()) OR public.has_role(auth.uid(),'admin') OR p.user_id=auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date,'vehicle_name',CASE WHEN p.module='vehicle' THEN p.vehicle_name ELSE NULL END,'vehicle_number',CASE WHEN p.module='vehicle' THEN p.vehicle_number ELSE NULL END,'driver_name',CASE WHEN p.module='vehicle' AND p.show_contact THEN p.driver_name ELSE NULL END,'contact_phone',CASE WHEN p.show_contact THEN p.contact_phone ELSE NULL END,'public_brand',CASE WHEN p.show_contact THEN p.public_brand ELSE '' END,'public_photo',CASE WHEN p.show_contact AND p.public_photo ~ '^https://' THEN p.public_photo ELSE '' END); END $$;
CREATE OR REPLACE FUNCTION public.list_free_work(_section text,_area text DEFAULT '',_category text DEFAULT '') RETURNS TABLE(id text,source text,category text,area text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id::text,'entry',e.category,e.area FROM public.free_work_entries e WHERE e.section=_section AND e.created_at+interval '30 days'>now() AND public.account_allowed(e.user_id) AND (_area='' OR lower(trim(e.area))=lower(trim(_area))) AND (_category='' OR public.free_work_category(e.category)=public.free_work_category(_category)) UNION ALL SELECT p.id::text,'post',coalesce(nullif(p.skill,''),p.category,p.title),coalesce(p.location,'') FROM public.posts p WHERE p.module='job' AND public.post_listing_visible(p) AND public.account_allowed(p.user_id) AND _section=CASE WHEN p.service_type='service' THEN CASE WHEN p.kind='seeker' THEN 'service-providers' ELSE 'service-wanted' END ELSE CASE WHEN p.kind='seeker' THEN 'work-wanted' ELSE 'work-offered' END END AND (_area='' OR lower(trim(p.location))=lower(trim(_area)) OR p.area_scope='country') AND (_category='' OR public.free_work_category(coalesce(nullif(p.skill,''),p.category,p.title))=public.free_work_category(_category)) UNION ALL SELECT s.user_id::text,'provider',coalesce(nullif(s.category,''),s.service),s.town FROM public.service_profiles s WHERE _section='service-providers' AND s.published AND public.account_allowed(s.user_id) AND (_area='' OR lower(trim(s.town))=lower(trim(_area))) AND (_category='' OR public.free_work_category(coalesce(nullif(s.category,''),s.service))=public.free_work_category(_category)); $$;
CREATE OR REPLACE FUNCTION public.list_free_work_interests(_section text,_area text DEFAULT '',_category text DEFAULT '') RETURNS TABLE(id text,source text,category text,area text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.id::text,'interest',i.category,i.area FROM public.free_work_interests i WHERE i.section=_section AND i.created_at+interval '30 days'>now() AND public.account_allowed(i.user_id) AND (_area='' OR lower(trim(i.area))=lower(trim(_area))) AND (_category='' OR public.free_work_category(i.category)=public.free_work_category(_category)); $$;